wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(124574420927471940293)
,p_plug_name=>'Tutorial 1'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc:t-CardsRegion--styleA'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    topic_id,',
'    CATEGORY AS card_categ,',
'    topic_no || '': '' || title AS card_title,',
'    summary AS card_text,',
'    CASE',
'       ',
'        WHEN ROUND(SYSDATE - LAST_UPDATED_DAYS) = 0 THEN ''Last Updated :  Today updated''',
'        WHEN ROUND(SYSDATE - LAST_UPDATED_DAYS) = 1 THEN ''Last Updated : 1 day ago''',
'        ELSE ''Last Updated : ''|| ROUND(SYSDATE - LAST_UPDATED_DAYS) || '' days ago''',
'    END AS card_subtext,',
'',
'    APEX_PAGE.GET_URL(',
'        p_page => CASE topic_id',
'                    WHEN 1 THEN 7',
'                    WHEN 2 THEN 8',
'                    WHEN 3 THEN 9',
'                    WHEN 4 THEN 10',
'                    WHEN 5 THEN 11',
'                    WHEN 6 THEN 12',
'                    WHEN 7 THEN 13',
'                    ELSE 14',
'                  END',
'    ) AS URL',
'FROM course_topics where CATEGORY LIKE''Orac%''',
'ORDER BY topic_no;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
