wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(124574421976073940304)
,p_plug_name=>'CONSTRAINTS'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!-- ========================= CONSTRAINTS ========================= -->',
'',
'<!-- <h2>CONSTRAINTS</h2> -->',
'',
'<p>',
'<b>Constraints</b> are rules applied on table columns to maintain',
'<b>data accuracy</b> and <b>data integrity</b> in a database.',
'</p>',
'',
'<p>',
'Constraints control what type of data can be stored in a table.',
'</p>',
'',
'<h3>Types of Constraints</h3>',
'<ol>',
'  <li><b>NOT NULL</b></li>',
'  <li><b>UNIQUE</b></li>',
'  <li><b>PRIMARY KEY</b></li>',
'  <li><b>FOREIGN KEY</b></li>',
'  <li><b>CHECK</b></li>',
'  <li><b>DEFAULT</b></li>',
'</ol>',
'',
'<hr>',
'',
'<!-- ========================= NOT NULL ========================= -->',
'',
'<h2>1. NOT NULL Constraint</h2>',
'',
'<p>',
'The <b>NOT NULL</b> constraint does not allow <b>NULL</b> values in a column.',
'</p>',
'',
'<b>Create Time Syntax:</b>',
'<pre>',
'CREATE TABLE table_name (',
'  column_name datatype NOT NULL',
');',
'</pre>',
'',
'<b>Example:</b>',
'<pre>',
'CREATE TABLE EMP (',
'  EMPNO NUMBER NOT NULL,',
'  ENAME VARCHAR2(30)',
');',
'</pre>',
'',
'<b>Add NOT NULL to Existing Table:</b>',
'<pre>',
'ALTER TABLE EMP MODIFY ENAME VARCHAR2(30) NOT NULL;',
'</pre>',
'',
'<hr>',
'',
'<!-- ========================= UNIQUE ========================= -->',
'',
'<h2>2. UNIQUE Constraint</h2>',
'',
'<p>',
'The <b>UNIQUE</b> constraint ensures that all values in a column are different.',
'It does <b>not allow duplicate values</b>, but it <b>accepts NULL values</b>.',
'</p>',
'',
'<b>Create Time Syntax:</b>',
'<pre>',
'CREATE TABLE table_name (',
'  column_name datatype UNIQUE',
');',
'</pre>',
'',
'<b>Example:</b>',
'<pre>',
'CREATE TABLE EMP (',
'  EMAIL VARCHAR2(50) UNIQUE',
');',
'</pre>',
'',
'<b>Add UNIQUE to Existing Table:</b>',
'<pre>',
'ALTER TABLE EMP',
'ADD CONSTRAINT emp_email_uk UNIQUE (EMAIL);',
'</pre>',
'',
'<hr>',
'',
'<!-- ========================= PRIMARY KEY ========================= -->',
'',
'<h2>3. PRIMARY KEY Constraint</h2>',
'',
'<p>',
'The <b>PRIMARY KEY</b> constraint uniquely identifies each record in a table.',
'</p>',
'',
'<ul>',
'  <li>Does not allow <b>NULL</b></li>',
'  <li>Does not allow <b>duplicate values</b></li>',
'</ul>',
'',
'<b>Create Time Syntax:</b>',
'<pre>',
'CREATE TABLE table_name (',
'  column_name datatype PRIMARY KEY',
');',
'</pre>',
'',
'<b>Example:</b>',
'<pre>',
'CREATE TABLE EMP (',
'  EMPNO NUMBER PRIMARY KEY,',
'  ENAME VARCHAR2(30)',
');',
'</pre>',
'',
'<b>Add PRIMARY KEY to Existing Table:</b>',
'<pre>',
'ALTER TABLE EMP',
'ADD CONSTRAINT emp_pk PRIMARY KEY (EMPNO);',
'</pre>',
'',
'<hr>',
'',
'<!-- ========================= FOREIGN KEY ========================= -->',
'',
'<h2>4. FOREIGN KEY Constraint</h2>',
'',
'<p>',
'The <b>FOREIGN KEY</b> constraint is used to create a relationship between two tables.',
'</p>',
'',
'<p>',
'It refers to the <b>PRIMARY KEY</b> of another (parent) table.',
'</p>',
'',
'<b>Create Time Syntax:</b>',
'<pre>',
'CREATE TABLE child_table (',
'  column_name datatype,',
'  FOREIGN KEY (column_name)',
'  REFERENCES parent_table(column_name)',
');',
'</pre>',
'',
'<b>Example:</b>',
'<pre>',
'CREATE TABLE EMP (',
'  EMPNO NUMBER PRIMARY KEY,',
'  DEPTNO NUMBER,',
'  FOREIGN KEY (DEPTNO) REFERENCES DEPT(DEPTNO)',
');',
'</pre>',
'',
'<b>Add FOREIGN KEY to Existing Table:</b>',
'<pre>',
'ALTER TABLE EMP',
'ADD CONSTRAINT emp_dept_fk',
'FOREIGN KEY (DEPTNO) REFERENCES DEPT(DEPTNO);',
'</pre>',
'',
'<hr>',
'',
'<!-- ========================= CHECK ========================= -->',
'',
'<h2>5. CHECK Constraint</h2>',
'',
'<p>',
'The <b>CHECK</b> constraint restricts the values allowed in a column.',
'</p>',
'',
'<b>Create Time Syntax:</b>',
'<pre>',
'CREATE TABLE table_name (',
'  column_name datatype CHECK (condition)',
');',
'</pre>',
'',
'<b>Example:</b>',
'<pre>',
'CREATE TABLE EMP (',
'  SAL NUMBER CHECK (SAL > 0)',
');',
'</pre>',
'',
'<b>Add CHECK to Existing Table:</b>',
'<pre>',
'ALTER TABLE EMP',
'ADD CONSTRAINT emp_sal_ck CHECK (SAL > 0);',
'</pre>',
'',
'<hr>',
'',
'<!-- ========================= DEFAULT ========================= -->',
'',
'<h2>6. DEFAULT Constraint</h2>',
'',
'<p>',
'The <b>DEFAULT</b> constraint sets a default value for a column when no value is provided.',
'</p>',
'',
'<b>Create Time Syntax:</b>',
'<pre>',
'CREATE TABLE table_name (',
'  column_name datatype DEFAULT value',
');',
'</pre>',
'',
'<b>Example:</b>',
'<pre>',
'CREATE TABLE EMP (',
'  STATUS VARCHAR2(10) DEFAULT ''ACTIVE''',
');',
'</pre>',
'',
'<b>Add DEFAULT to Existing Table:</b>',
'<pre>',
'ALTER TABLE EMP',
'MODIFY STATUS VARCHAR2(10) DEFAULT ''ACTIVE'';',
'</pre>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
/
