wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(124730608493349004222)
,p_plug_name=>'SQL Wildcards'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!-- ========================= SQL WILDCARDS (EASY ENGLISH) ========================= -->',
'',
'<!-- <h2>SQL WILDCARDS</h2> -->',
'',
'<p>',
'<b>SQL Wildcards</b> are special characters used with the <b>LIKE</b> operator',
'to <b>search patterns in data</b>.',
'</p>',
'',
'<p>',
'In very simple words:',
'<br>',
'<b>Wildcard = search data when exact value is not known</b>',
'</p>',
'',
'<hr>',
'',
'<h2>Why Do We Use Wildcards?</h2>',
'',
'<p>',
'Wildcards are used when:',
'</p>',
'',
'<ul>',
'  <li>We know only part of the data</li>',
'  <li>We want to search similar values</li>',
'  <li>Exact match is not possible</li>',
'</ul>',
'',
'<hr>',
'',
'<h2>Types of Wildcards in SQL</h2>',
'',
'<ol>',
'  <li><b>%</b> (Percent)</li>',
'  <li><b>_</b> (Underscore)</li>',
'</ol>',
'',
'<hr>',
'',
'<!-- ========================= % WILDCARD ========================= -->',
'',
'<h2>1. % (Percent) Wildcard</h2>',
'',
'<p>',
'The <b>%</b> wildcard represents <b>zero, one, or many characters</b>.',
'</p>',
'',
'<p>',
'Simple meaning:',
'<br>',
'<b>% = any number of characters</b>',
'</p>',
'',
'<b>Examples:</b>',
'<pre>',
'-- Names starting with ''S''',
'SELECT ename FROM emp WHERE ename LIKE ''S%'';',
'',
'-- Names ending with ''H''',
'SELECT ename FROM emp WHERE ename LIKE ''%H'';',
'',
'-- Names containing ''AR''',
'SELECT ename FROM emp WHERE ename LIKE ''%AR%'';',
'</pre>',
'',
'<hr>',
'',
'<!-- ========================= _ WILDCARD ========================= -->',
'',
'<h2>2. _ (Underscore) Wildcard</h2>',
'',
'<p>',
'The <b>_</b> wildcard represents <b>exactly one character</b>.',
'</p>',
'',
'<p>',
'Simple meaning:',
'<br>',
'<b>_ = only one character</b>',
'</p>',
'',
'<b>Examples:</b>',
'<pre>',
'-- Names with 4 letters',
'SELECT ename FROM emp WHERE ename LIKE ''____'';',
'',
'-- Names starting with ''S'' and ending with ''H''',
'SELECT ename FROM emp WHERE ename LIKE ''S__H'';',
'</pre>',
'',
'<hr>',
'',
'<h2>Using % and _ Together</h2>',
'',
'<p>',
'We can combine wildcards to create powerful search patterns.',
'</p>',
'',
'<b>Example:</b>',
'<pre>',
'-- Names starting with ''A'' and having at least 3 characters',
'SELECT ename FROM emp WHERE ename LIKE ''A__%'';',
'</pre>',
'',
'<hr>',
'',
'<h2>Important Points</h2>',
'',
'<ul>',
'  <li>Wildcards are used with the <b>LIKE</b> operator</li>',
'  <li><b>%</b> matches many characters</li>',
'  <li><b>_</b> matches only one character</li>',
'</ul>',
'',
'<hr>',
'',
'<h2>In Simple Words</h2>',
'',
'<p>',
'<b>SQL Wildcards</b> help search data based on patterns',
'when the exact value is unknown.',
'</p>',
'',
'<p>',
unistr('<b>%</b> \2192 many characters<br>'),
unistr('<b>_</b> \2192 one character'),
'</p>',
''))
,p_ai_enabled=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
