wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(125051394763044435688)
,p_plug_name=>'Packages'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!-- ========================= PL/SQL MODULE 10 : PACKAGES ========================= -->',
'',
'<!-- <h2>Module 10: Packages</h2> -->',
'',
'',
'<p>',
'This module explains how to group related',
'<b>procedures, functions, variables, and cursors</b>',
'using <b>PL/SQL Packages</b>.',
'</p>',
'',
'<p>',
'Packages help in writing',
'<b>organized, reusable, and secure</b> code.',
'</p>',
'',
'<hr>',
'',
'<h3>52. What is a Package?</h3>',
'',
'<p>',
'A <b>Package</b> is a collection of related',
'PL/SQL program units stored together.',
'</p>',
'',
'<p>',
'It contains two parts:',
'</p>',
'',
'<ul>',
'  <li><b>Package Specification</b></li>',
'  <li><b>Package Body</b></li>',
'</ul>',
'',
'<hr>',
'',
'<h3>53. Package Specification</h3>',
'',
'<p>',
'The <b>Package Specification</b> declares',
'what is visible to users.',
'</p>',
'',
'<p>',
'It contains declarations of:',
'</p>',
'',
'<ul>',
'  <li>Procedures</li>',
'  <li>Functions</li>',
'  <li>Variables</li>',
'  <li>Cursors</li>',
'</ul>',
'',
'<b>Example:</b>',
'<pre>',
'CREATE OR REPLACE PACKAGE emp_pkg IS',
'  PROCEDURE add_emp(p_empno NUMBER, p_name VARCHAR2);',
'  FUNCTION get_sal(p_empno NUMBER) RETURN NUMBER;',
'END emp_pkg;',
'</pre>',
'',
'<hr>',
'',
'<h3>54. Package Body</h3>',
'',
'<p>',
'The <b>Package Body</b> contains',
'the actual implementation of',
'procedures and functions.',
'</p>',
'',
'<b>Example:</b>',
'<pre>',
'CREATE OR REPLACE PACKAGE BODY emp_pkg IS',
'',
'  PROCEDURE add_emp(p_empno NUMBER, p_name VARCHAR2) IS',
'  BEGIN',
'    INSERT INTO emp(empno, ename)',
'    VALUES (p_empno, p_name);',
'  END;',
'',
'  FUNCTION get_sal(p_empno NUMBER) RETURN NUMBER IS',
'    v_sal NUMBER;',
'  BEGIN',
'    SELECT sal INTO v_sal FROM emp WHERE empno = p_empno;',
'    RETURN v_sal;',
'  END;',
'',
'END emp_pkg;',
'</pre>',
'',
'<hr>',
'',
'<h3>55. Advantages of Packages</h3>',
'',
'<ul>',
'  <li>Improves performance</li>',
'  <li>Better code organization</li>',
'  <li>Provides data security</li>',
'  <li>Easy maintenance</li>',
'</ul>',
'',
'<hr>',
'',
'<h3>56. Calling Package Members</h3>',
'',
'<p>',
'Procedures and functions inside a package',
'are called using the package name.',
'</p>',
'',
'<b>Example:</b>',
'<pre>',
'BEGIN',
'  emp_pkg.add_emp(9001, ''DEV'');',
'END;',
'</pre>',
'',
'<b>Function Call:</b>',
'<pre>',
'SELECT emp_pkg.get_sal(7369) FROM dual;',
'</pre>',
'',
'<hr>',
'',
'<h2>In Simple Words</h2>',
'',
'<p>',
'<b>Module 10</b> explains how PL/SQL packages',
'group related code together.',
'</p>',
'',
'<p>',
'Packages make applications',
'<b>clean, fast, and secure</b>.',
'</p>',
''))
,p_ai_enabled=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
/
